import 'package:cloud_firestore/cloud_firestore.dart';
import 'chat_models.dart';
class ChatRepository { ChatRepository(this.db); final FirebaseFirestore db; Stream<List<MessageModel>> watchMessages(String conversationId)=>db.collection('conversations').doc(conversationId).collection('messages').orderBy('createdAt').snapshots().map((s)=>s.docs.map((d)=>MessageModel.fromMap(d.id,d.data())).toList()); Future<void> send(MessageModel message) async { final batch=db.batch(); final conversation=db.collection('conversations').doc(message.conversationId); batch.set(conversation,{'participantIds':FieldValue.arrayUnion([message.senderId,if(message.receiverId!=null)message.receiverId]),'lastMessage':message.text,'updatedAt':FieldValue.serverTimestamp()},SetOptions(merge:true)); batch.set(conversation.collection('messages').doc(message.id),message.toMap()); await batch.commit(); } Future<void> delete(String conversationId,String messageId)=>db.collection('conversations').doc(conversationId).collection('messages').doc(messageId).update({'isDeleted':true,'text':'','updatedAt':FieldValue.serverTimestamp()}); Future<void> toggleReaction(MessageModel message,String userId,String reaction) { final values=Map<String,List<String>>.from(message.reactions); final users=List<String>.from(values[reaction]??[]); users.contains(userId)?users.remove(userId):users.add(userId); users.isEmpty?values.remove(reaction):values[reaction]=users; return db.collection('conversations').doc(message.conversationId).collection('messages').doc(message.id).update({'reactions':values}); } }
